#include "stdlib/lapack/base/dgbtf2.h"
#include "validate.h"

/**
* Computes a band LU factorization with partial row pivoting.
*
* @param order  storage layout
* @param M      number of dense rows
* @param N      number of dense columns
* @param KL     number of subdiagonals
* @param KU     number of superdiagonals
* @param AB     compact band input/output
* @param LDAB   leading dimension of the compact view
* @param PIV    positive one-based stepwise row interchanges
* @return       INFO or a negative argument position
*/
LAPACK_INT API_SUFFIX(c_dgbtf2)( const LAPACK_LAYOUT order, const LAPACK_INT M, const LAPACK_INT N, const LAPACK_INT KL, const LAPACK_INT KU, double *AB, const LAPACK_INT LDAB, LAPACK_INT *PIV ) {
	LAPACK_INT kv;
	LAPACK_INT h;
	LAPACK_INT k;
	LAPACK_INT stride1;
	LAPACK_INT stride2;
	LAPACK_INT info;

	if ( order != LAPACK_ROW_MAJOR && order != LAPACK_COL_MAJOR ) return dgbtf2_error( "c_dgbtf2", -1 );
	info = dgbtf2_dimensions( 1, M, N, KL, KU, &kv, &h, &k );
	if ( info != 0 ) return dgbtf2_error( "c_dgbtf2", info );
	if ( ( order == LAPACK_COL_MAJOR && LDAB < h ) || ( order == LAPACK_ROW_MAJOR && ( LDAB < 1 || LDAB < N ) ) ) return dgbtf2_error( "c_dgbtf2", -7 );
	if ( M == 0 || N == 0 ) return 0;
	stride1 = order == LAPACK_COL_MAJOR ? 1 : LDAB;
	stride2 = order == LAPACK_COL_MAJOR ? LDAB : 1;
	info = dgbtf2_validate( 1, M, N, KL, KU, AB, stride1, stride2, 0, PIV, 1, 0 );
	if ( info != 0 ) return dgbtf2_error( "c_dgbtf2", info );
	return API_SUFFIX(c_dgbtf2_ndarray)( M, N, KL, KU, AB, stride1, stride2, 0, PIV, 1, 0 );
}
